def _tool_text(content: object) -> str:
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts: list[str] = []
        for block in content:
            if isinstance(block, str):
                parts.append(block)
            elif isinstance(block, dict) and isinstance(block.get("text"), str):
                parts.append(block["text"])
        return "".join(parts)
    return ""


def _pass_through(message: ToolMessage) -> dict[str, Any]:
    """Use the MCP tool result as the query payload."""
    artifact = message.artifact
    if isinstance(artifact, dict):
        structured = artifact.get("structured_content")
        if isinstance(structured, dict):
            return structured
    text = _tool_text(message.content)
    try:
        payload = json.loads(text) if text else None
    except json.JSONDecodeError as exc:
        raise ExplorerError("database returned a non-object") from exc
    if not isinstance(payload, dict):
        raise ExplorerError("database returned a non-object")
    return payload


